void CCodabase::Init(const char* szDirectory, EDurableSync eSync, CLifeInit<CIndexedDataConfig> cIndexConfig, CLifeInit<CNamedIndexesConfig> cNamedConfig)
{
CIndexTreeHelper cHelper;
cHelper.Init(szDirectory, "Primary", "Backup", false);
mbControllerInitialised = mcFileController.Init(cHelper.GetPrimaryDirectory(), cHelper.GetBackupDirectory());
mcFileController.SetSync(eSync);
mcIndexConfig = cIndexConfig;
mcNamedConfig = cNamedConfig;
mbStarted = false;
mcMutex.Init();
mbFailed = false;
mcVersions.Init();
miCommitNumber = 0;
maiSnapshots.Init();
mcLocks.Init();
mcReservedNames.Init(true, true);
miLastStartNumber = 0;
mapcWriters.Init();
mcSessionMutex.Init();
mcSessionFinished.Init();
mpcSession = 0L;
miSessionThread = 0;
cHelper.Kill(false);
}
bool CCodabase::Start(void)
{
bool bResult;
if (mbStarted)
{
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 53, __PRETTY_FUNCTION__), " Codabase has already been started.", 0L);
}
if (!mbControllerInitialised)
{
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 57, __PRETTY_FUNCTION__), " Codabase file controller could not be initialised.", 0L);
}
mcMutex.Lock();
bResult = mcFileController.Recover();
if (!bResult)
{
mcMutex.Unlock();
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 65, __PRETTY_FUNCTION__), " Codabase could not recover from an incomplete commit.", 0L);
}
bResult = mcFileController.Begin();
if (bResult)
{
mcNamedIndexedData.Init(&mcFileController, mcIndexConfig, mcNamedConfig);
mbStarted = true;
bResult = mcFileController.End();
bResult = bResult && mcFileController.Begin();
}
mcMutex.Unlock();
return bResult;
}
void CCodabase::Kill(void)
{
CLife<CIndexedDataConfig> cIndexLife;
CLife<CNamedIndexesConfig> cNamedLife;
CIndexedDataConfig* pcIndexConfig;
CNamedIndexesConfig* pcNamedConfig;
if (mpcSession != 0L)
{
if (mpcSession) { mpcSession->Kill(); free(mpcSession); mpcSession = 0L; };
}
if (mbStarted)
{
mcFileController.Abort();
mcNamedIndexedData.Kill();
}
else
{
mcIndexConfig.ConfigureLife(&cIndexLife, &pcIndexConfig);
cIndexLife.Kill();
mcNamedConfig.ConfigureLife(&cNamedLife, &pcNamedConfig);
cNamedLife.Kill();
}
mcFileController.Kill();
mcVersions.Kill();
maiSnapshots.Kill();
mcLocks.Kill();
mcReservedNames.Kill();
mapcWriters.Kill();
mcSessionFinished.Kill();
mcSessionMutex.Kill();
mcMutex.Kill();
}
bool CCodabase::Open(void)
{
CWriteTransaction* pcSession;
if (!mbStarted)
{
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 135, __PRETTY_FUNCTION__), " Cannot open a Codabase that is not started.", 0L);
}
if (HasWriterOnThisThread())
{
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 139, __PRETTY_FUNCTION__), " This thread already has a write transaction.  The session could wait for it for ever.", 0L);
}
mcSessionMutex.Lock();
if ((mpcSession != 0L) && (miSessionThread == CurrentThreadId()))
{
mcSessionMutex.Unlock();
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 147, __PRETTY_FUNCTION__), " This thread already has the Codabase open.  Waiting for itself would never end.", 0L);
}
while (mpcSession != 0L)
{
mcSessionFinished.Wait(&mcSessionMutex);
}
if (IsFailed())
{
mcSessionMutex.Unlock();
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 156, __PRETTY_FUNCTION__), " A commit failed.  The Codabase is read only until it is restarted.", 0L);
}
pcSession = NewMalloc<CWriteTransaction>();
pcSession->Init(this, 0);
mpcSession = pcSession;
miSessionThread = CurrentThreadId();
mcSessionMutex.Unlock();
return true;
}
bool CCodabase::Close(void)
{
bool bResult;
mcSessionMutex.Lock();
if (mpcSession == 0L)
{
mcSessionMutex.Unlock();
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 180, __PRETTY_FUNCTION__), " Cannot close a Codabase that is not open.", 0L);
}
bResult = mpcSession->Commit();
if (mpcSession) { mpcSession->Kill(); free(mpcSession); mpcSession = 0L; };
miSessionThread = 0;
mcSessionFinished.WakeAll();
mcSessionMutex.Unlock();
return bResult;
}
CWriteTransaction* CCodabase::BeginWriteTransaction(void)
{
CWriteTransaction* pcTransaction;
int64 iStartNumber;
bool bSessionThread;
if (!mbStarted)
{
gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 204, __PRETTY_FUNCTION__), " Cannot begin a write transaction on a Codabase that is not started.", 0L);
return 0L;
}
mcSessionMutex.Lock();
bSessionThread = (mpcSession != 0L) && (miSessionThread == CurrentThreadId());
mcSessionMutex.Unlock();
if (bSessionThread)
{
gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 213, __PRETTY_FUNCTION__), " This thread has the Codabase open.  The session could wait for the transaction for ever.", 0L);
return 0L;
}
mcMutex.Lock();
if (mbFailed)
{
mcMutex.Unlock();
gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 222, __PRETTY_FUNCTION__), " A commit failed.  The Codabase is read only until it is restarted.", 0L);
return 0L;
}
miLastStartNumber++;
iStartNumber = miLastStartNumber;
pcTransaction = NewMalloc<CWriteTransaction>();
pcTransaction->Init(this, iStartNumber);
mapcWriters.Add(pcTransaction);
mcMutex.Unlock();
return pcTransaction;
}
CReadTransaction* CCodabase::BeginReadTransaction(void)
{
CReadTransaction* pcTransaction;
int64 iSnapshot;
if (!mbStarted)
{
gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 246, __PRETTY_FUNCTION__), " Cannot begin a read transaction on a Codabase that is not started.", 0L);
return 0L;
}
mcMutex.Lock();
iSnapshot = miCommitNumber;
maiSnapshots.Add(iSnapshot);
mcMutex.Unlock();
pcTransaction = NewMalloc<CReadTransaction>();
pcTransaction->Init(this, iSnapshot);
return pcTransaction;
}
size CCodabase::NumVersions(void)
{
size uiNumVersions;
mcMutex.Lock();
uiNumVersions = mcVersions.NumVersions();
mcMutex.Unlock();
return uiNumVersions;
}
bool CCodabase::IsFailed(void)
{
bool bFailed;
mcMutex.Lock();
bFailed = mbFailed;
mcMutex.Unlock();
return bFailed;
}
bool CCodabase::CommitLocked(void)
{
bool bResult;
if (mbFailed)
{
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 303, __PRETTY_FUNCTION__), " A commit failed.  The Codabase is read only until it is restarted.", 0L);
}
bResult = true;
if (!mcNamedIndexedData.IsWriteThrough())
{
bResult = mcNamedIndexedData.Flush(false);
}
bResult = bResult && mcFileController.End();
bResult = bResult && mcFileController.Begin();
if (!bResult)
{
mbFailed = true;
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 317, __PRETTY_FUNCTION__), " Commit failed.  The Codabase is read only until it is restarted.", 0L);
}
miCommitNumber++;
RemoveOldVersions();
return true;
}
CLockManager* CCodabase::GetLockManager(void)
{
return &mcLocks;
}
bool CCodabase::NeedsSession(const char* szMethod)
{
return gcLogger.Error2(szMethod, " Writing directly to a Codabase needs Open first.  Use a write transaction otherwise.", 0L);
}
bool CCodabase::HasWriterOnThisThread(void)
{
size i;
int iThread;
bool bFound;
iThread = CurrentThreadId();
bFound = false;
mcMutex.Lock();
for (i = 0; i < mapcWriters.NumElements(); i++)
{
if ((*mapcWriters.Get(i))->GetThread() == iThread)
{
bFound = true;
break;
}
}
mcMutex.Unlock();
return bFound;
}
void CCodabase::RemoveWriter(CWriteTransaction* pcTransaction)
{
size i;
mcMutex.Lock();
for (i = 0; i < mapcWriters.NumElements(); i++)
{
if (*mapcWriters.Get(i) == pcTransaction)
{
mapcWriters.RemoveAt(i);
break;
}
}
mcMutex.Unlock();
}
bool CCodabase::ReserveName(const char* szName, int64 iTransaction, bool bRemovedByTransaction)
{
int64* piOwner;
mcMutex.Lock();
if (!bRemovedByTransaction && (mcNamedIndexedData.GetIndex(szName) != ((OIndex)-1)))
{
mcMutex.Unlock();
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 413, __PRETTY_FUNCTION__), " Cannot Add Name [", szName, "].  It already exists.", 0L);
}
piOwner = mcReservedNames.Get(szName);
if ((piOwner != 0L) && (*piOwner != iTransaction))
{
mcMutex.Unlock();
return gcLogger.Error2(MethodToString("/home/r2d2/Codaphela/commonlibraries/BaseLib/Codabase.cpp", 419, __PRETTY_FUNCTION__), " Cannot Add Name [", szName, "].  Another transaction is adding it.", 0L);
}
if (piOwner == 0L)
{
mcReservedNames.Put(szName, &iTransaction);
}
mcMutex.Unlock();
return true;
}
void CCodabase::ReleaseNames(CArrayChars* paszNames, int64 iTransaction)
{
size i;
int64* piOwner;
char* szName;
mcMutex.Lock();
for (i = 0; i < paszNames->NumElements(); i++)
{
szName = paszNames->GetText(i);
piOwner = mcReservedNames.Get(szName);
if ((piOwner != 0L) && (*piOwner == iTransaction))
{
mcReservedNames.Remove(szName);
}
}
mcMutex.Unlock();
}
